/* ── AI CHAT ── */
function AIChatPage({ dark }) {
  const [messages, setMessages] = useState([{role:"assistant",content:"Hi! I'm Puja's AI assistant. I know her complete background — every project, every agent, every pipeline. Ask me anything!"}]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const endRef = useRef(null);
  const bg=dark?"#080c16":"#f7f9ff"; const txt=dark?"#e4e8f4":"#0a0f1e";
  const sub=dark?"rgba(228,232,244,0.45)":"rgba(10,15,30,0.5)";
  const cardBg=dark?"rgba(255,255,255,0.025)":"rgba(255,255,255,0.85)";
  const cardBorder=dark?"rgba(255,255,255,0.07)":"rgba(0,0,0,0.07)";
  const quick=["What makes Puja stand out?","Tell me about her 5 AI agents","Biggest project she's owned?","Summarize for a Data Engineer role","What is her telehealth AI tool?","What full-stack work has she done?"];
  useEffect(()=>{endRef.current?.scrollIntoView({behavior:"smooth"});},[messages,loading]);
  async function send(text) {
    const msg=text||input.trim(); if(!msg) return;
    setInput(""); const updated=[...messages,{role:"user",content:msg}];
    setMessages(updated); setLoading(true);
    try {
      const res=await fetch("/api/chat",{method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({system:SYSTEM_PROMPT,messages:updated.map(m=>({role:m.role,content:m.content}))})});
      const data=await res.json();
      const reply=(data&&data.reply)||(data&&data.error)||"Sorry, something went wrong.";
      setMessages(p=>[...p,{role:"assistant",content:reply}]);
    } catch{setMessages(p=>[...p,{role:"assistant",content:"Connection error. Please try again."}]);}
    setLoading(false);
  }
  return (
    <div style={{minHeight:"100vh",background:bg,paddingTop:80,paddingBottom:80}}>
      <div style={{maxWidth:1100,margin:"0 auto",padding:"0 clamp(16px,4vw,60px)"}}>
        <div style={{marginBottom:40}}>
          <div style={{color:"#00D4AA",fontSize:11,letterSpacing:"0.14em",textTransform:"uppercase",marginBottom:12,fontWeight:600}}>Interactive</div>
          <h2 style={{fontFamily:"'Bricolage Grotesque',sans-serif",fontSize:40,fontWeight:800,color:txt,letterSpacing:"-0.025em",marginBottom:8}}>Talk to My Resume</h2>
          <p style={{color:sub,fontSize:14,fontWeight:300}}>AI assistant trained on Puja's complete background.</p>
          <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"center",marginTop:16}}>
            <span style={{color:sub,fontSize:12}}>Recruiter mode:</span>
            {Object.entries(recruiterModes).map(([role,summary])=>(
              <details key={role} style={{position:"relative"}}>
                <summary style={{background:dark?"rgba(255,255,255,0.04)":"rgba(0,0,0,0.04)",border:`1px solid ${dark?"rgba(255,255,255,0.08)":"rgba(0,0,0,0.07)"}`,borderRadius:9,padding:"6px 14px",color:sub,fontSize:12,cursor:"pointer",listStyle:"none",outline:"none"}}>
                  {role}
                </summary>
                <div style={{position:"absolute",top:"calc(100% + 8px)",left:0,zIndex:50,background:dark?"#111827":"#fff",border:"1px solid rgba(0,212,170,0.2)",borderRadius:14,padding:"16px 18px",width:380,fontSize:13,color:sub,lineHeight:1.75,boxShadow:"0 16px 40px rgba(0,0,0,0.4)"}}>
                  <div style={{color:"#00D4AA",fontSize:10,fontWeight:700,marginBottom:8}}>✦ {role.toUpperCase()}</div>
                  {summary}
                </div>
              </details>
            ))}
          </div>
        </div>
        <div style={{display:"grid",gridTemplateColumns:"1fr 1.4fr",gap:26,alignItems:"start"}}>
          <div>
            <img src={img2_resume} alt="" style={{width:"100%",borderRadius:14,marginBottom:20,objectFit:"contain",maxHeight:210}}/>
            <div style={{color:sub,fontSize:11,letterSpacing:"0.08em",marginBottom:10,fontWeight:500}}>TRY ASKING</div>
            <div style={{display:"flex",flexDirection:"column",gap:7}}>
              {quick.map(q=>(
                <button key={q} onClick={()=>send(q)} style={{background:dark?"rgba(255,255,255,0.03)":"rgba(0,0,0,0.03)",border:`1px solid ${dark?"rgba(255,255,255,0.07)":"rgba(0,0,0,0.07)"}`,borderRadius:9,padding:"9px 13px",color:sub,fontSize:12.5,cursor:"pointer",textAlign:"left",transition:"all 0.2s"}}
                  onMouseEnter={e=>{e.target.style.borderColor="rgba(0,212,170,0.3)";e.target.style.color=txt;}}
                  onMouseLeave={e=>{e.target.style.borderColor=dark?"rgba(255,255,255,0.07)":"rgba(0,0,0,0.07)";e.target.style.color=sub;}}>
                  {q}
                </button>
              ))}
            </div>
          </div>
          <div style={{background:cardBg,border:`1px solid ${cardBorder}`,borderRadius:18,overflow:"hidden",display:"flex",flexDirection:"column",height:520}}>
            <div style={{padding:"13px 17px",borderBottom:`1px solid ${cardBorder}`,display:"flex",alignItems:"center",gap:10,background:dark?"rgba(0,212,170,0.04)":"rgba(0,212,170,0.06)"}}>
              <div style={{width:32,height:32,borderRadius:"50%",background:"linear-gradient(135deg,#00D4AA,#7C5CFC)",display:"flex",alignItems:"center",justifyContent:"center",fontSize:13,fontWeight:800,color:"#fff"}}>P</div>
              <div><div style={{color:txt,fontWeight:600,fontSize:13}}>Puja AI</div><div style={{color:"#00D4AA",fontSize:10}}>● online · knows everything</div></div>
            </div>
            <div style={{flex:1,overflowY:"auto",padding:"14px",display:"flex",flexDirection:"column",gap:9}}>
              {messages.map((m,i)=>(
                <div key={i} style={{display:"flex",justifyContent:m.role==="user"?"flex-end":"flex-start"}}>
                  <div style={{maxWidth:"80%",padding:"9px 13px",borderRadius:m.role==="user"?"14px 14px 4px 14px":"14px 14px 14px 4px",background:m.role==="user"?"linear-gradient(135deg,#00D4AA,#0099ff)":(dark?"rgba(255,255,255,0.06)":"rgba(0,0,0,0.05)"),color:m.role==="user"?"#fff":txt,fontSize:13,lineHeight:1.6,whiteSpace:"pre-wrap"}}>{m.content}</div>
                </div>
              ))}
              {loading&&<div style={{display:"flex"}}><div style={{background:dark?"rgba(255,255,255,0.06)":"rgba(0,0,0,0.05)",borderRadius:"14px 14px 14px 4px"}}><TypingDots/></div></div>}
              <div ref={endRef}/>
            </div>
            <div style={{padding:"10px 13px",borderTop:`1px solid ${cardBorder}`,display:"flex",gap:8}}>
              <input value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&!loading&&send()} placeholder="Ask about experience, projects, skills…" style={{flex:1,background:dark?"rgba(255,255,255,0.05)":"rgba(0,0,0,0.04)",border:`1px solid ${cardBorder}`,borderRadius:10,padding:"9px 13px",color:txt,fontSize:12.5,outline:"none"}}/>
              <button onClick={()=>!loading&&send()} disabled={loading||!input.trim()} style={{width:35,height:35,borderRadius:9,background:input.trim()?"linear-gradient(135deg,#00D4AA,#0099ff)":(dark?"rgba(255,255,255,0.06)":"rgba(0,0,0,0.06)"),border:"none",cursor:input.trim()?"pointer":"default",color:input.trim()?"#fff":sub,fontSize:15,display:"flex",alignItems:"center",justifyContent:"center"}}>↑</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

